/* Invitation-only onboarding, brochure catalogue and money/payment operations. */
function portalAuth(){
 const forgot=portal.authMode==='forgot',reset=portal.authMode==='reset',invite=portal.authMode==='invite';
 const title=reset?'Set your password.':invite?'Verify your invitation.':forgot?'Recover your account.':'Welcome back.';
 return `<main class="portal-auth-layout"><section class="portal-auth-story"><img class="portal-auth-logo" src="/sigma0nine-logo.png" alt="Sigma0Nine"><span class="eyebrow">YOUR PARTNER WORKSPACE</span><h1>Your business.<br>Connected.</h1><p>Private policy uploads, clear approvals and earnings in one place.</p></section><section class="portal-auth-main"><div class="portal-auth-card"><span class="eyebrow">${portalEntry.role==='admin'?'ADMIN':'PARTNER'} ACCESS</span><h1>${title}</h1><p>${reset?'Your email has been verified. Choose a password to finish setting up your account.':invite?'Enter the email and one-time code from your admin invitation, or open the verification link in that email.':forgot?'We will email a reset link if the account exists.':'Accounts are created by your administrator. Sign in with your verified email and password.'}</p>${portalInlineError(portal.authError)}${portal.authMessage?`<p class="notice" role="status">${pe(portal.authMessage)}</p>`:''}<form id="portalAuthForm" onsubmit="event.preventDefault();portalSubmitAuth(this)">${!reset?`<label class="field">Email<input name="email" type="email" required autocomplete="email" maxlength="254" value="${pe(portal.authEmail||'')}"></label>`:''}${invite?'<label class="field">Invitation code<input name="token" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,10}" minlength="6" maxlength="10" required></label>':!forgot?`<label class="field">${reset?'New password':'Password'}<input name="password" type="password" required ${reset?'minlength="12"':''} autocomplete="${reset?'new-password':'current-password'}"></label>${reset?'<label class="field">Confirm password<input name="confirmPassword" type="password" required minlength="12" autocomplete="new-password"></label>':''}`:''}<button class="primary" type="submit" ${portal.busy?'disabled':''}>${portal.busy?'Please wait…':reset?'Save password & open workspace':invite?'Verify code':forgot?'Send reset link':'Sign in'}</button>${!reset&&!invite&&!forgot?'<button class="portal-email-link" type="button" onclick="portalEmailLink(this.form)">Email me a sign-in link</button>':''}</form>${!reset?`<div class="portal-auth-switch">${portalButton(forgot||invite?'Back to sign in':'Forgot password?',`portalSetAuthMode('${forgot||invite?'login':'forgot'}')`)}</div>`:''}<p class="portal-auth-switch"><a href="${portalWorkspaceUrl(portalEntry.role==='admin'?'partner':'admin')}">Open ${portalEntry.role==='admin'?'partner':'admin'} sign in</a></p><div class="portal-auth-foot">${I('lock')}Invitation only · Contact your administrator for a new account.</div></div></section></main>`;
}
async function portalSubmitAuth(form){
 if(portal.busy)return;portal.busy=true;portal.authError='';portal.authMessage='';const values=new FormData(form),mode=portal.authMode;form.querySelector('button[type=submit]').disabled=true;
 try{
  const email=String(values.get('email')||'').trim();portal.authEmail=email;
  if(mode==='register')throw Error('Only your administrator can create an account.');
  if(mode==='invite'){
   const token=String(values.get('token')||'').trim();if(!/^[0-9]{6,10}$/.test(token))throw Error('Enter the code from your invitation email');
   const result=await portal.client.auth.verifyOtp({email,token,type:'invite'});if(result.error)throw result.error;
   if(!result.data.session)throw Error('Verification did not open a session. Request a fresh invitation.');
   portal.recovery=true;portal.authMode='reset';portal.authMessage='Email verified. Set your password to continue.';await portalHandleSession(result.data.session);
  }else if(mode==='forgot'){
   const result=await portal.client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+portalEntry.path});if(result.error)throw result.error;portal.authMessage='If this email is registered, a password reset link will arrive shortly.';
  }else if(mode==='reset'){
   const password=String(values.get('password')||'');if(password.length<12)throw Error('Use at least 12 characters');if(password!==String(values.get('confirmPassword')||''))throw Error('Passwords do not match');
   const result=await portal.client.auth.updateUser({password});if(result.error)throw result.error;portal.recovery=false;portal.authMode='login';history.replaceState(null,'',portalEntry.path+(portalEntry.role==='admin'?'#admin':'#partner'));await portalHandleSession((await portal.client.auth.getSession()).data.session);portalNotify('Password saved');
  }else{
   const result=await portal.client.auth.signInWithPassword({email,password:String(values.get('password')||'')});if(result.error)throw result.error;await portalHandleSession(result.data.session);
  }
 }catch(e){portal.authError=portalError(e)}finally{portal.busy=false;portalRender()}
}
async function portalEmailLink(form){
 if(portal.busy||!form.elements.email.reportValidity())return;portal.authEmail=form.elements.email.value.trim();portal.busy=true;portal.authError='';portal.authMessage='';
 try{const result=await portal.client.auth.signInWithOtp({email:portal.authEmail,options:{shouldCreateUser:false,emailRedirectTo:location.origin+portalEntry.path}});if(result.error)throw result.error;portal.authMessage='Check your email for the sign-in link. New accounts must be invited by an administrator.'}catch(e){portal.authError=portalError(e)}finally{portal.busy=false;portalRender()}
}
function portalBrochuresPage(){return heading('PRODUCT LIBRARY','Brochures','Product information and documents supplied by your team.',portalModeAdmin()?portalButton('Manage brochure links',"portalRoute('referral-settings')",'file',true):'')+`<div class="referral-cards brochure-cards">${referralProducts.map(p=>`<article class="card pad"><span class="service-icon">${I('file')}</span><h2>${pe(p[1])}</h2><p>${pe(p[4])}</p>${referralLink(p[0]+'-brochure','Open brochure')}</article>`).join('')}</div><section class="card pad"><h2>More product resources</h2>${referralLink('brochures','Open brochure library')}</section>`}
const partnerAdmin={rows:[],invites:[],loading:false,error:'',limit:50};
async function portalLoadPartners(){if(!portalModeAdmin())return;partnerAdmin.loading=true;partnerAdmin.error='';try{const [users,invites]=await Promise.all([portal.client.from('sigma_profiles').select('id,full_name,email,role,created_at').eq('role','partner').order('created_at',{ascending:false}).limit(partnerAdmin.limit),portal.client.from('sigma_partner_invites').select('id,email,full_name,status,created_at,last_attempt_at').order('created_at',{ascending:false}).limit(partnerAdmin.limit)]);if(users.error||invites.error)throw users.error||invites.error;partnerAdmin.rows=users.data||[];partnerAdmin.invites=invites.data||[]}catch(e){partnerAdmin.error=portalError(e)}finally{partnerAdmin.loading=false;if(portal.view==='agents')portalRender()}}
function portalAgentsPage(){if(!portalModeAdmin())return portalInlineError('Admin access required');if(!partnerAdmin.loaded){partnerAdmin.loaded=true;portalLoadPartners()}return heading('PARTNER ADMINISTRATION','Manage partners','Invite a partner by email. They verify the email and set their own password.',portalButton('Refresh list','portalLoadPartners()','renew'))+`<div class="business-grid"><section class="card pad"><h2>Create partner account</h2><button type="button" onclick="portalCheckInvitation(this)">Check invitation service</button><p data-invite-check role="status"></p><form onsubmit="event.preventDefault();portalInvitePartner(this)"><label class="field">Partner name<input name="fullName" required minlength="2" maxlength="100" autocomplete="name"></label><label class="field">Email<input name="email" type="email" required maxlength="254" autocomplete="email"></label><p class="subtle">The email contains a secure activation link. An invitation code is available when the email provider is configured to include it. Only partner access is created.</p><div class="portal-form-error" role="alert"></div><div class="portal-form-success" role="status"></div><button type="submit" class="primary">Send account invitation</button></form></section><section class="card pad"><h2>How onboarding works</h2><ol class="onboarding-steps"><li>You enter the partner name and email.</li><li>The partner verifies the invitation by code or email link.</li><li>They choose a password and open their workspace.</li></ol><p>Self-registration is closed. Existing partners keep their accounts.</p></section></div>${portalInlineError(partnerAdmin.error)}<section class="card"><div class="cardhead"><h2>Partner accounts</h2><span>${partnerAdmin.loading?'Loading…':'Latest '+partnerAdmin.rows.length+' accounts'}</span></div><div class="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Created</th></tr></thead><tbody>${partnerAdmin.rows.map(p=>`<tr><td>${pe(p.full_name)}</td><td>${pe(p.email)}</td><td>${pe(portalDate(p.created_at))}</td></tr>`).join('')||'<tr><td colspan="3">Refresh the list to see partner accounts.</td></tr>'}</tbody></table></div></section><section class="card" style="margin-top:20px"><div class="cardhead"><h2>Invitation history</h2></div><div class="tablewrap"><table><thead><tr><th>Partner</th><th>Email</th><th>Email delivery request</th><th>Last attempt</th></tr></thead><tbody>${partnerAdmin.invites.map(p=>`<tr><td>${pe(p.full_name)}</td><td>${pe(p.email)}</td><td>${pe(p.status)}</td><td>${pe(portalDate(p.last_attempt_at))}</td></tr>`).join('')||'<tr><td colspan="4">No invitations loaded.</td></tr>'}</tbody></table></div></section><div class="actions">${portalButton('Load older accounts','partnerAdmin.limit+=50;portalLoadPartners()','plus')}</div>`}
async function portalInvitePartner(form){if(!portalModeAdmin()||portal.busy)return;portal.busy=true;const button=form.querySelector('button[type=submit]');button.disabled=true;form.querySelector('.portal-form-error').textContent='';form.querySelector('.portal-form-success').textContent='';try{const data=new FormData(form),result=await portal.client.functions.invoke('admin-partners',{body:{email:String(data.get('email')).trim(),fullName:String(data.get('fullName')).trim()}});if(result.error){let detail;try{detail=await result.error.context.json()}catch{}throw Error(detail?.error||result.error.message)}if(!result.data?.sent)throw Error('Invitation was not sent');form.reset();form.querySelector('.portal-form-success').textContent=result.data.message;portalNotify('Account invitation sent');await portalLoadPartners()}catch(e){form.querySelector('.portal-form-error').textContent=portalError(e)}finally{portal.busy=false;button.disabled=false}}
function portalPaymentFor(credit){const receipt=credit?.sigma_payment_receipts;return Array.isArray(receipt)?receipt[0]:receipt}
function portalPaymentDetails(credit){const r=portalPaymentFor(credit);return `<section class="payment-detail"><h3>Payment receipt</h3>${r?`<span class="badge">Payment recorded by admin</span><p>UTR: <strong>${pe(r.utr||'Screenshot provided')}</strong><br>Payment date: ${pe(r.paid_on)}<br>${pe(r.note||'')}</p>${r.storage_path?portalButton('Open payment proof',`portalPaymentDocument('${r.id}')`,'file'):''}`:`<p>Payment is pending. Earnings have been credited to the account.</p>${portalModeAdmin()&&Number(credit.amount_paise)>0?portalButton('Record payment / attach proof',`portalPaymentForm('${credit.id}')`,'wallet',true):''}`}<div id="payment-document-link"></div><div id="payment-document-error" role="alert"></div></section>`}
function portalWalletPage(){const admin=portalModeAdmin(),s=portal.summary;return heading('EARNINGS & PAYMENTS',admin?'Partner earnings ledger':'My earnings','Track awarded amounts and payment receipts.',portalButton('Refresh','portalRefresh()','renew'))+`<div class="metrics">${metric('Total earnings',PortalCore.money(s.amount_paise||0),'wallet','Confirmed earning credits')}${metric('Payment recorded',PortalCore.money(portal.paymentSummary?.paid_paise||0),'check','Receipts recorded by admin')}${metric('Awaiting payment',PortalCore.money(portal.paymentSummary?.unpaid_paise||0),'clock','Earned but no payment receipt yet')}${metric('Credited policies',s.credited||0,'shield','One earning award per policy')}</div><section class="card"><div class="cardhead"><h2>Earnings & receipt history</h2></div>${portal.ledger.length?`<div class="tablewrap"><table><thead><tr>${admin?'<th>Partner</th>':''}<th>Customer / policy</th><th>Amount</th><th>Payment / UTR</th><th>Credited</th><th>Action</th></tr></thead><tbody>${portal.ledger.map(l=>{const receipt=portalPaymentFor(l);return `<tr>${admin?`<td>${pe(l.owner_profile?.full_name||'Partner')}<small>${pe(l.owner_profile?.email||'')}</small></td>`:''}<td><strong>${pe(l.policy?.customer_name||'Policy')}</strong><small>${pe(l.policy?.policy_number||l.policy_id.slice(0,8))}</small></td><td>${PortalCore.money(l.amount_paise)}</td><td>${receipt?`<strong>${pe(receipt.utr||'Screenshot attached')}</strong><small>${pe(receipt.paid_on)} · Admin recorded</small>`:'Awaiting payment'}</td><td>${pe(portalDate(l.created_at))}</td><td>${receipt?.storage_path?portalButton('View proof',`portalPaymentDocument('${receipt.id}')`,'file'):''}${admin&&!receipt&&Number(l.amount_paise)>0?portalButton('Record payment',`portalPaymentForm('${l.id}')`,'wallet',true):''}${portalButton('View policy',`portalPolicyDetails('${l.policy_id}')`,'file')}</td></tr>`}).join('')}</tbody></table></div>`:emptyCard('No earnings yet','Earnings appear after an administrator approves a policy and awards its amount.')}${portal.ledgerHasMore?portalButton('Load more history','portal.limit+=50;portalRefresh()','plus'):''}</section><div id="payment-document-link"></div><div id="payment-document-error" role="alert"></div>`}
function portalCreditForm(id){if(!portalModeAdmin())return;const p=portal.policies.find(p=>p.id===PortalCore.uuid(id));if(!p||p.status!=='Approved'||portalCreditFor(p))return;modal('Award partner earnings',`<div class="portal-credit-recipient"><span class="initial">${portalInitial(portalOwner(p).full_name)}</span><div><strong>${pe(portalOwner(p).full_name)}</strong><small>${pe(portalOwner(p).email)}</small></div></div><p>Policy for <strong>${pe(p.customer_name)}</strong> · ${pe(p.policy_number||p.id.slice(0,8))}</p><form onsubmit="event.preventDefault();portalPreviewCredit('${id}',this)"><label class="field">Earning amount (₹)<input name="money" type="number" min="0.01" max="1000000000" step="0.01" required placeholder="0.00"></label><label class="field">Earning note<textarea name="note" rows="3" maxlength="2000"></textarea></label><p class="subtle">This awards the earning amount. Record the UTR or payment proof after the transfer is completed.</p><div class="portal-form-error" role="alert"></div><div class="modalfoot">${portalButton('Back',`portalPolicyDetails('${id}')`)}<button class="primary" type="submit">Review earning amount</button></div></form>`)}
function portalPreviewCredit(id,form){try{const data=new FormData(form),amount=PortalCore.paise(data.get('money'));if(amount<=0)throw Error('Enter a positive earning amount');portalPendingCredit={policyId:PortalCore.uuid(id),points:0,amount_paise:amount,note:String(data.get('note')||'')};const p=portal.policies.find(p=>p.id===id);modal('Confirm earning award',`<p>Credit <strong>${pe(portalOwner(p).full_name)}</strong><br>${pe(portalOwner(p).email)}</p><div class="portal-credit-preview"><div><span>Earning amount</span><strong>${PortalCore.money(amount)}</strong></div></div><p>${pe(p.customer_name)} · ${pe(p.product)}<br>${pe(portalPendingCredit.note)}</p><div id="portal-credit-error" role="alert"></div><div class="modalfoot">${portalButton('Back',`portalCreditForm('${id}')`)}<button type="button" class="primary" onclick="portalConfirmCredit(this)">Confirm & award amount</button></div>`)}catch(e){form.querySelector('.portal-form-error').textContent=portalError(e)}}
function portalFindCredit(id){return portal.ledger.find(l=>l.id===id)||portal.policies.map(p=>portalCreditFor(p)).find(l=>l?.id===id)}
function portalPaymentForm(id){if(!portalModeAdmin())return;const credit=portalFindCredit(PortalCore.uuid(id));if(!credit||portalPaymentFor(credit)||Number(credit.amount_paise)<=0)return;const p=portal.policies.find(p=>p.id===credit.policy_id)||portal.policies.find(p=>portalCreditFor(p)?.id===id);modal('Record partner payment',`<p><strong>${pe(credit.owner_profile?.full_name||portalOwner(p||{}).full_name)}</strong> · ${PortalCore.money(credit.amount_paise)}<br>${pe(p?.customer_name||credit.policy?.customer_name||'Approved policy')}</p><form onsubmit="event.preventDefault();portalRecordPayment('${id}',this)"><label class="field">UTR / transaction reference<input name="utr" maxlength="40" pattern="[A-Za-z0-9/-]{6,40}" placeholder="Bank transaction reference"></label><label class="field">Payment date<input name="paidOn" type="date" required max="${dateISO()}" value="${dateISO()}"></label><label class="field">Payment screenshot or receipt<input name="proof" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"><small>Private document · up to 10 MB. Supply a UTR or a proof file, or both.</small></label><label class="field">Payment note<textarea name="note" maxlength="2000" rows="3"></textarea></label><p class="notice">Record this only after the payment is completed. This saves a receipt; it does not initiate a bank transfer.</p><label class="payment-confirm"><input type="checkbox" required name="confirmed"> I checked the recipient, amount and payment proof.</label><div class="portal-form-error" role="alert"></div><div class="modalfoot"><button class="primary" type="submit">Save payment receipt</button></div></form>`)}
async function portalRecordPayment(id,form){if(!portalModeAdmin()||portal.busy)return;portal.busy=true;const button=form.querySelector('button[type=submit]');button.disabled=true;try{const credit=portalFindCredit(id);if(!credit)throw Error('Reload the earning entry');if(!form.paymentAttempt){const data=new FormData(form),file=form.elements.proof.files[0],utr=String(data.get('utr')||'').trim().toUpperCase();if(utr&&!/^[A-Z0-9/-]{6,40}$/.test(utr))throw Error('Enter a valid UTR');if(!utr&&!file)throw Error('Enter a UTR or attach a payment proof');const args={p_ledger_id:PortalCore.uuid(id),p_utr:utr,p_paid_on:String(data.get('paidOn')),p_note:String(data.get('note')||''),p_storage_path:null,p_file_name:null,p_file_type:null,p_file_size:null};if(file){const ext=await PortalCore.validateFile(file);Object.assign(args,{p_storage_path:credit.owner_id+'/'+id+'/'+crypto.randomUUID()+'.'+ext,p_file_name:file.name.slice(0,200),p_file_type:file.type,p_file_size:file.size})}form.paymentAttempt={args,file,uploaded:false}}const attempt=form.paymentAttempt;if(attempt.file&&!attempt.uploaded){button.textContent='Uploading private proof…';const uploaded=await portal.client.storage.from('sigma-payment-proofs').upload(attempt.args.p_storage_path,attempt.file,{contentType:attempt.file.type,upsert:false,cacheControl:'0'});if(uploaded.error&&!/already exists|duplicate/i.test(uploaded.error.message))throw uploaded.error;attempt.uploaded=true}const result=await portal.client.rpc('sigma_record_payment',attempt.args);if(result.error)throw result.error;closeModal();await portalRefresh();portalNotify('Payment receipt saved for the partner')}catch(e){form.querySelector('.portal-form-error').textContent=portalError(e);if(form.paymentAttempt){for(const input of form.querySelectorAll('input,textarea'))input.disabled=true;button.textContent='Retry same receipt'}}finally{portal.busy=false;button.disabled=false}}
async function portalPaymentDocument(id){try{let receipt;for(const credit of [...portal.ledger,...portal.policies.map(p=>portalCreditFor(p)).filter(Boolean)]){const r=portalPaymentFor(credit);if(r?.id===PortalCore.uuid(id))receipt=r}if(!receipt?.storage_path)throw Error('Payment proof is not available');const result=await portal.client.storage.from('sigma-payment-proofs').createSignedUrl(receipt.storage_path,60,{download:receipt.original_file_name});if(result.error)throw result.error;(document.querySelector('#overlay #payment-document-link')||document.querySelector('#payment-document-link')).innerHTML=`<p><a href="${pe(result.data.signedUrl)}" target="_blank" rel="noopener noreferrer">Download ${pe(receipt.original_file_name)}</a> · private link expires in 60 seconds</p>`}catch(e){(document.querySelector('#overlay #payment-document-error')||document.querySelector('#payment-document-error')).textContent=portalError(e)}}

async function portalCheckInvitation(button){if(!portalModeAdmin())return;button.disabled=true;const status=document.querySelector('[data-invite-check]');try{const result=await portal.client.functions.invoke('admin-partners',{body:{checkOnly:true}});if(result.error){let detail;try{detail=await result.error.context.json()}catch{}throw Error(detail?.error||detail?.message||result.error.message)}if(!result.data?.authorized)throw Error('Service authorization could not be confirmed');status.textContent=result.data.message}catch(e){status.textContent=portalError(e)}finally{button.disabled=false}}
const adminUpload={people:[],query:'',limit:50,loading:false,error:'',request:0};
function portalUploaderName(p){if(p.uploaded_by&&p.uploaded_by!==p.owner_id)return (p.uploader_profile?.full_name||'Administrator')+' · uploaded on partner’s behalf';return p.uploader_profile?.full_name||portalOwner(p).full_name}
function portalChooseUploadPartner(){if(!portalModeAdmin())return;adminUpload.query='';adminUpload.limit=50;adminUpload.people=[];adminUpload.error='';portalRenderPartnerPicker();portalSearchUploadPartners()}
function portalRenderPartnerPicker(){if(!portalModeAdmin())return;modal('Choose partner for policy upload',`<p>The policy and any approved earnings will belong to the selected partner. Your administrator account is recorded as the uploader.</p><form data-partner-picker onsubmit="event.preventDefault();adminUpload.query=this.search.value;adminUpload.limit=50;portalSearchUploadPartners()"><div class="toolbar"><div class="searchbox">${I('search')}<input name="search" aria-label="Search partner accounts" placeholder="Search name or email…" maxlength="100" value="${pe(adminUpload.query)}"></div><button class="primary" type="submit">Search</button></div></form>${portalInlineError(adminUpload.error)}<div class="partner-picker-list">${adminUpload.loading?'<p role="status">Loading partner accounts…</p>':adminUpload.people.map(p=>`<button type="button" class="partner-picker-option" onclick="portalSelectUploadPartner('${PortalCore.uuid(p.id)}')"><span class="initial">${portalInitial(p.full_name)}</span><span><strong>${pe(p.full_name)}</strong><small>${pe(p.email)}</small></span><span>Choose</span></button>`).join('')||'<p>No partner accounts found. An existing partner account is required before uploading on their behalf.</p>'}</div>${!adminUpload.loading&&adminUpload.people.length>=adminUpload.limit?portalButton('Load more partners','adminUpload.limit+=50;portalSearchUploadPartners()','plus'):''}<div class="modalfoot">${portalButton('Cancel','closeModal()')}</div>`)}
async function portalSearchUploadPartners(){if(!portalModeAdmin())return;const request=++adminUpload.request;adminUpload.loading=true;adminUpload.error='';portalRenderPartnerPicker();try{let query=portal.client.from('sigma_profiles').select('id,full_name,email,role').eq('role','partner').order('full_name',{ascending:true}).limit(adminUpload.limit);const search=adminUpload.query.replace(/[^\p{L}\p{N}@. _+'-]/gu,'').trim();if(search)query=query.or('full_name.ilike.*'+search+'*,email.ilike.*'+search+'*');const result=await query;if(result.error)throw result.error;if(request===adminUpload.request)adminUpload.people=result.data||[]}catch(e){if(request===adminUpload.request)adminUpload.error=portalError(e)}finally{if(request===adminUpload.request){adminUpload.loading=false;if(portalModeAdmin()&&document.querySelector('[data-partner-picker]'))portalRenderPartnerPicker()}}}
function portalSelectUploadPartner(id){if(!portalModeAdmin())return;const person=adminUpload.people.find(p=>p.id===PortalCore.uuid(id)&&p.role==='partner');if(!person)return toast('Choose an existing partner account');portalRenderUploadForm(person)}
